package com.tamo.service;
import com.tamo.model.*;
import org.junit.jupiter.api.Test;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
class SecurityBoundaryTest{
 @Test void passwordsUseSaltedHashesAndRejectWrongPassword(){String a=PasswordSecurity.hash("Synthetic-password"),b=PasswordSecurity.hash("Synthetic-password");assertNotEquals(a,b);assertTrue(PasswordSecurity.encoded(a));assertTrue(PasswordSecurity.verify("Synthetic-password",a));assertFalse(PasswordSecurity.verify("wrong",a));assertFalse(PasswordSecurity.verify("wrong","pbkdf2$1$x$x"));}
 @Test void documentPathsCannotEscapePrivateStorage(){Profile.Document doc=new Profile.Document();doc.setName("../../secrets");assertThrows(QualificationService.Problem.class,()->PrivateDocuments.path(doc));doc.setStorageKey("../secret.pdf");assertThrows(QualificationService.Problem.class,()->PrivateDocuments.path(doc));}
 @Test void documentAccessRequiresOwnershipOrSubmittedDocumentAndCourseGrant(){DataStore ds=TestDataFactory.createTestDataStore();assertNotNull(PrivateDocuments.authorized(ds,"u001","doc001"));assertThrows(QualificationService.Problem.class,()->PrivateDocuments.authorized(ds,"u002","doc001"));assertNotNull(PrivateDocuments.authorized(ds,"u005","doc001"));assertThrows(QualificationService.Problem.class,()->PrivateDocuments.authorized(ds,"u006","doc001"));}
 @Test void roleChangeRemovesOldCustomWriteGrants(){DataStore ds=TestDataFactory.createTestDataStore();User staff=ds.getUsers().stream().filter(u->u.getId().equals("u006")).findFirst().orElseThrow();staff.setRole("decision_maker");staff.setPermissions(List.of("review.read","review.approve"));var data=org.mockito.Mockito.mock(JsonDataService.class);org.mockito.Mockito.when(data.getData()).thenReturn(ds);var body=new com.google.gson.JsonObject();body.addProperty("role","viewer");new AdminService(data).updateUser("u007",staff.getId(),body);assertNull(staff.getPermissions());assertFalse(ReviewAccess.can(staff,"review.approve"));assertTrue(ReviewAccess.can(staff,"review.read"));}
 @Test void administratorPasswordUpdateActuallyChangesHashedCredential(){DataStore ds=TestDataFactory.createTestDataStore();var data=org.mockito.Mockito.mock(JsonDataService.class);org.mockito.Mockito.when(data.getData()).thenReturn(ds);var body=new com.google.gson.JsonObject();body.addProperty("password","Synthetic-new-password");var result=new AdminService(data).updateUser("u006","u001",body);assertFalse(result.containsKey("error"));String stored=ds.getUsers().get(0).getPassword();assertTrue(PasswordSecurity.encoded(stored));assertTrue(PasswordSecurity.verify("Synthetic-new-password",stored));body.addProperty("password","");assertEquals(400,new AdminService(data).updateUser("u006","u001",body).get("code"));}
 @Test void rejectedApplicationDocumentRemainsPrivateForUnassignedViewer(){DataStore ds=TestDataFactory.createTestDataStore();User viewer=new User();viewer.setId("viewer");viewer.setStatus("active");viewer.setRole("viewer");viewer.setCourseIds(List.of());ds.getUsers().add(viewer);assertThrows(QualificationService.Problem.class,()->PrivateDocuments.authorized(ds,"viewer","doc001"));}
}
